    // ========== Partition C: Defect-Targeted Branch Zone ==========

    /**
     * Defect: When @JsonFormat(shape = STRING) is used without pattern,
     * the serializer should produce a string "1970-01-01" (default ISO8601)
     * but the bug produces numeric 0.
     * This test directly targets that branch.
     */
    @Test(timeout = 4000)
    public void testDateDefaultShapeWithStringShapeNoPattern() {
        // Simulate the exact scenario from the defect:
        // - property has @JsonFormat(shape = STRING) with no pattern
        // - serializer should use default ISO8601 pattern
        TestDateSerializer serializer = new TestDateSerializer();
        TestSerializerProvider prov = new TestSerializerProvider();
        
        // Create format with STRING shape, no pattern
        JsonFormat.Value format = JsonFormat.Value.forShape(JsonFormat.Shape.STRING);
        BeanProperty prop = new TestBeanProperty(format);
        
        JsonSerializer<?> result = serializer.createContextual(prov, prop);
        assertTrue("Should return new instance", result instanceof TestDateSerializer);
        TestDateSerializer resultSer = (TestDateSerializer) result;
        
        // The defect: _useTimestamp should be FALSE, not TRUE
        assertEquals("useTimestamp should be FALSE for STRING shape", Boolean.FALSE, resultSer._useTimestamp);
        assertNotNull("customFormat should be set", resultSer._customFormat);
        
        // Verify the format produces "1970-01-01" for epoch
        SimpleDateFormat sdf = (SimpleDateFormat) resultSer._customFormat;
        assertEquals("Default pattern should be ISO8601", StdDateFormat.DATE_FORMAT_STR_ISO8601, sdf.toPattern());
        String formatted = sdf.format(new java.util.Date(0L));
        assertEquals("Epoch should be formatted as 1970-01-01", "1970-01-01", formatted);
        
        // Also verify _asTimestamp returns false (string serialization)
        assertFalse("Should serialize as string, not timestamp", resultSer._asTimestamp(prov));
    }

    @Test(timeout = 4000)
    public void testDateDefaultShapeWithStringShapeAndPattern() {
        TestDateSerializer serializer = new TestDateSerializer();
        TestSerializerProvider prov = new TestSerializerProvider();
        
        JsonFormat.Value format = JsonFormat.Value.forPattern("yyyy/MM/dd");
        BeanProperty prop = new TestBeanProperty(format);
        
        JsonSerializer<?> result = serializer.createContextual(prov, prop);
        TestDateSerializer resultSer = (TestDateSerializer) result;
        assertEquals(Boolean.FALSE, resultSer._useTimestamp);
        SimpleDateFormat sdf = (SimpleDateFormat) resultSer._customFormat;
        assertEquals("yyyy/MM/dd", sdf.toPattern());
        assertEquals("1970/01/01", sdf.format(new java.util.Date(0L)));
    }

